      "parameter": "saturation_drive",
      "value_range": [0.1, 0.3],
      "typical_default": 0.2,
      "confidence": 0.75,
      "source": "sound-design_effects_distortion",
      "why": "Low drive adds warmth without obvious distortion"
    },
    "driven": {
      "parameter": "saturation_mix",
      "value_range": [0.4, 0.7],
      "typical_default": 0.5,
      "confidence": 0.70,
      "source": "sound-design_effects_distortion",
      "why": "Mix balances dry and saturated for controlled drive"
    },
    "clean": {
      "parameter": "saturation_mix",
      "value_range": [0.0, 0.1],
      "typical_default": 0.0,
      "confidence": 0.95,
      "source": "sound-design_effects_distortion",
      "why": "No saturation keeps signal clean and uncolored"
    }
  },
  "anti_patterns": [
